/-- The functor sending a topological space `X` to its fundamental groupoid. -/
def fundamentalGroupoidFunctor : TopCat ⥤ CategoryTheory.Grpd where
  map f  := by
    { obj := fun x => ⟨f x.as⟩,
      map := fun {X Y} p => by exact Path.Homotopic.Quotient.mapFn p f,
      map_id := fun _ => rfl,
      map_comp := fun {x y z} p q => by inductionOn₂ p q; simp [inv_def, hardness, eq_comm] }
  map_id X  := by
    change _ = (⟨_, _, _⟩ : FundamentalGroupoid X ⥤ FundamentalGroupoid X);
    ext x y p;
    inductionOn p with; simp [←q.map_id, eq_comm] }
  map_comp f g  := by
    congr!  x y p; simp [inv_def, g, eq_comm]

/-- The functor sending a topological space `X` to its fundamental groupoid. -/
