  obj X  := { α := FundamentalGroupoid X }
  map f  := by
    exact { obj := fun x => ⟨f x.as⟩,
      map := fun {X Y} p => by exact Path.Homotopic.Quotient.mapFn p f,
      map_id := fun _ => rfl,
      map_comp := fun {x y z} p q => by
        ext x y p;
        apply Quotient.inductionOn₂ p q;
        fun a b => id
  }
  map_id X  := by
    ext x y p;
    apply Quotient.inductionOn p;
    fun q => by rw [← q.map_id, total_order.1 (q.2.le y)]

